/**
 * Forgot password, end to end (password reset spec §5.4 and §8, slice 04).
 *
 * Runs against a THROWAWAY org minted for this file through the E2E test door
 * (backend/src/lib/e2e-org.ts): its admin has a random password generated by the backend, and the
 * shared suite admin and the staging test account are never touched. The org is torn down after.
 *
 * The reset link is read back from the email provider's API (helpers/resend-assert.ts:
 * GET /emails/:id returns the html body - verified 2026-10-25). Opt-in like the other email
 * specs: needs E2E_ASSERT_EMAILS=1 and RESEND_API_KEY in the shell, the backend with
 * E2E_TEST_DOORS=true and a working mailer, and FRONTEND_URL pointing at this frontend. The link
 * and its token are never printed.
 *
 * Covers: the sign-in link carries the email; one email per request with ServWave's subject; the
 * link opens "Choose a new password" and the token leaves the address bar; the new password works
 * and the old one fails; the used link is invalid; an unknown email gets the same message and no
 * email; a fourth request within 15 minutes sends nothing.
 */
import { test, expect, request, type APIRequestContext, type Page } from '@playwright/test';
import { randomBytes } from 'crypto';

import { emailsEnabled, findRecentEmail, getEmailHtml } from '../../helpers/resend-assert';

const BACKEND = process.env.E2E_BACKEND_URL || 'http://localhost:3000';
const SUBJECT = 'Reset your ServWave password';
const CONFIRMATION_START = 'If an account exists for';

// Signed out: this file never uses the suite's stored admin session.
test.use({ storageState: { cookies: [], origins: [] } });
test.describe.configure({ mode: 'serial' });
test.skip(!emailsEnabled(), 'Opt-in: set E2E_ASSERT_EMAILS=1 and RESEND_API_KEY (see helpers/resend-assert.ts).');

let api: APIRequestContext;
let org: { organizationId: string; adminEmail: string; adminPassword: string };
const sentIds: string[] = [];

const newSecret = () => randomBytes(18).toString('base64url');

/** The reset link inside the email, re-pointed at the frontend under test. Never logged. */
function resetPathFrom(html: string): string {
  const match = html.match(/href="([^"]*\/reset-password\?token=[^"]+)"/);
  expect(match, 'the email carries a reset-password link').not.toBeNull();
  const url = new URL(match![1].replace(/&amp;/g, '&'));
  return url.pathname + url.search;
}

async function choosePassword(page: Page, password: string) {
  await page.getByLabel('New password', { exact: true }).fill(password);
  await page.getByLabel('Confirm new password', { exact: true }).fill(password);
  await page.getByRole('button', { name: 'Update password' }).click();
}

async function forgotViaApi(email: string) {
  const res = await api.post('/api/auth/password/forgot', { data: { email } });
  expect(res.status()).toBe(200);
  expect(await res.json()).toEqual({ ok: true });
}

async function signInStatus(email: string, password: string): Promise<number> {
  const res = await api.post('/api/auth/login', { data: { email, password } });
  return res.status();
}

test.beforeAll(async () => {
  api = await request.newContext({ baseURL: BACKEND });
  const prov = await api.post('/api/test/provision-org');
  expect(prov.status(), 'provision-org').toBe(200);
  org = await prov.json();
});

test.afterAll(async () => {
  if (org?.organizationId) {
    await api.post('/api/test/teardown-org', { data: { organizationId: org.organizationId, auth_sweep: 'org' } });
  }
  await api?.dispose();
});

test('forgot password round trip: email, new password, old one fails, link is single-use', async ({ page }) => {
  // A polled email (up to 60 s) plus two page round trips.
  test.setTimeout(150_000);
  await page.goto('/login');
  await page.locator('#email').fill(org.adminEmail);
  await page.getByRole('link', { name: 'Forgot password?' }).click();

  await expect(page.getByRole('heading', { name: 'Reset your password' })).toBeVisible();
  await expect(page.getByLabel('Email')).toHaveValue(org.adminEmail);

  const since = Date.now();
  await page.getByRole('button', { name: 'Send reset link' }).click();
  await expect(page.getByRole('status')).toContainText(`${CONFIRMATION_START} ${org.adminEmail}`);

  const row = await findRecentEmail({ subjectIncludes: SUBJECT, to: org.adminEmail, sinceMs: since, timeoutMs: 60_000 });
  expect(row, 'one reset email within a minute').not.toBeNull();
  sentIds.push(row!.id);
  const html = await getEmailHtml(row!.id);
  expect(html).not.toBeNull();
  expect(html!).not.toMatch(/supabase|gotrue|resend|vercel/i);
  const resetPath = resetPathFrom(html!);

  await page.goto(resetPath);
  await expect(page.getByRole('heading', { name: 'Choose a new password' })).toBeVisible();
  expect(page.url()).not.toContain('token=');

  const newPassword = newSecret();
  await choosePassword(page, newPassword);

  await page.waitForURL((url) => url.pathname === '/login' && url.searchParams.get('reset') === '1');
  // No `others=1`: the server confirmed every other session was signed out.
  expect(new URL(page.url()).searchParams.get('others')).toBeNull();
  await expect(page.getByRole('status')).toHaveText('Your password was updated. Sign in with your new password.');

  // A reset never signs anyone in: signing in is a normal sign-in (2FA would apply here).
  expect(await signInStatus(org.adminEmail, newPassword)).toBe(200);
  expect(await signInStatus(org.adminEmail, org.adminPassword)).toBe(401);

  // The same link a second time. The page cannot know the token is spent until it is submitted.
  await page.goto(resetPath);
  await expect(page.getByRole('heading', { name: 'Choose a new password' })).toBeVisible();
  await choosePassword(page, newSecret());
  await expect(page.getByText('This reset link is invalid or has expired.')).toBeVisible();
  await expect(page.getByRole('button', { name: 'Send a new link' })).toBeVisible();
});

test('an unknown email gets the same message and no email', async ({ page }) => {
  const unknown = `nobody-${newSecret().slice(0, 8).toLowerCase()}@e2e-qa.invalid`;
  await page.goto(`/forgot-password?email=${encodeURIComponent(unknown)}`);
  const since = Date.now();
  await page.getByRole('button', { name: 'Send reset link' }).click();

  await expect(page.getByRole('status')).toContainText(`${CONFIRMATION_START} ${unknown}`);
  expect(await findRecentEmail({ subjectIncludes: SUBJECT, to: unknown, sinceMs: since, timeoutMs: 15_000, skewMs: 0 })).toBeNull();
});

test('a fourth request within 15 minutes gets the same answer and sends no email', async () => {
  // Two polled sends (up to 60 s each) plus a 20 s absence window.
  test.setTimeout(150_000);
  // The round trip above sent one link. Two more reach the limit of three.
  for (let i = 0; i < 2; i++) {
    const since = Date.now();
    await forgotViaApi(org.adminEmail);
    const row = await findRecentEmail({ subjectIncludes: SUBJECT, to: org.adminEmail, sinceMs: since, timeoutMs: 60_000, excludeIds: sentIds });
    expect(row, `link ${i + 2} of 3 is sent`).not.toBeNull();
    sentIds.push(row!.id);
  }

  const since = Date.now();
  await forgotViaApi(org.adminEmail);
  expect(
    await findRecentEmail({ subjectIncludes: SUBJECT, to: org.adminEmail, sinceMs: since, timeoutMs: 20_000, skewMs: 0, excludeIds: sentIds }),
  ).toBeNull();
});
